-- DI MODA — full mock catalog seed (40 products: 20 women, 20 men)
-- Generated from src/data/products.ts. Run AFTER schema.sql.
-- Safe to re-run: uses ON CONFLICT to upsert by id.
-- Delete the single 'seed-001' demo row first if you don't want it mixed in:
--   delete from public.products where id = 'seed-001';

on conflict (id) do update set
  slug = excluded.slug,
  name = excluded.name,
  gender = excluded.gender,
  category = excluded.category,
  price = excluded.price,
  compare_at_price = excluded.compare_at_price,
  images = excluded.images,
  colors = excluded.colors,
  sizes = excluded.sizes,
  description = excluded.description,
  details = excluded.details,
  tags = excluded.tags,
  rating = excluded.rating,
  review_count = excluded.review_count,
  in_stock = excluded.in_stock;
