  ('w-001', 'aurelia-silk-slip-dress', 'Aurelia Silk Slip Dress', 'women', 'dresses', 189, null, '["https://images.unsplash.com/photo-1595777457583-95e059d581b8?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1496747611176-843222e1e57c?auto=format&fit=crop&w=1000&q=80"]', '[{"name":"Ivory","hex":"#EDE8DC"},{"name":"Black","hex":"#1C1A17"},{"name":"Burgundy","hex":"#6E1E2B"}]', '["XS","S","M","L","XL"]', 'A bias-cut slip dress in fluid silk satin that skims the body. Adjustable straps, a subtle cowl neckline and a midi length that moves beautifully from day to evening.', '["100% mulberry silk","Bias cut, midi length","Adjustable spaghetti straps","Dry clean only"]', '["new","bestseller"]', 4.9, 124, true, '2026-11-13T20:24:26.484Z'),
  ('w-002', 'valentina-wrap-midi-dress', 'Valentina Wrap Midi Dress', 'women', 'dresses', 145, 185, '["https://images.unsplash.com/photo-1515372039744-b8f02a3ae446?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1559551409-dadc959f76b8?auto=format&fit=crop&w=1000&q=80"]', '[{"name":"Emerald","hex":"#1F6B4E"},{"name":"Black","hex":"#1C1A17"},{"name":"Blush","hex":"#E8C4C4"}]', '["XS","S","M","L","XL"]', 'The dress you reach for when you need to feel effortless. Flattering wrap front, flutter sleeves and a tie waist that cinches at exactly the right place.', '["Viscose crepe","True wrap with inner tie","Flutter sleeve","Machine wash cold"]', '["sale"]', 4.7, 88, true, '2026-10-06T20:24:26.485Z'),
  ('w-003', 'celeste-linen-shirt-dress', 'Celeste Linen Shirt Dress', 'women', 'dresses', 128, null, '["https://images.unsplash.com/photo-1624378439575-d8705ad7ae80?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1485968579580-b6d095142e6e?auto=format&fit=crop&w=1000&q=80"]', '[{"name":"White","hex":"#F6F5F1"},{"name":"Sage","hex":"#A8B5A0"},{"name":"Stone","hex":"#C9C2B4"}]', '["XS","S","M","L","XL"]', 'Relaxed, breathable and endlessly wearable. A classic shirt dress cut from European linen with a removable self-tie belt and side pockets.', '["100% European linen","Removable belt","Side seam pockets","Machine wash cold"]', '["new"]', 4.6, 41, true, '2026-11-10T20:24:26.485Z'),
  ('w-004', 'noor-evening-gown', 'Noor Evening Gown', 'women', 'dresses', 320, null, '["https://images.unsplash.com/photo-1551232864-3f0890e580d9?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1539533018447-63fcce2678e3?auto=format&fit=crop&w=1000&q=80"]', '[{"name":"Black","hex":"#1C1A17"},{"name":"Gold","hex":"#C8911B"},{"name":"Burgundy","hex":"#6E1E2B"}]', '["XS","S","M","L","XL"]', 'Floor-sweeping and unapologetically glamorous. A fitted bodice with delicate draping and a soft A-line skirt for the nights that matter.', '["Satin crepe with lining","Concealed back zip","Floor length","Dry clean only"]', '["limited"]', 5, 19, true, '2026-11-03T20:24:26.485Z'),
  ('w-005', 'mira-satin-blouse', 'Mira Satin Blouse', 'women', 'tops', 79, null, '["https://images.unsplash.com/photo-1516762689617-e1cffcef479d?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1612336307429-8a898d10e223?auto=format&fit=crop&w=1000&q=80"]', '[{"name":"Ivory","hex":"#EDE8DC"},{"name":"Blush","hex":"#E8C4C4"},{"name":"Black","hex":"#1C1A17"},{"name":"Emerald","hex":"#1F6B4E"}]', '["XS","S","M","L","XL"]', 'A fluid satin blouse with a relaxed collar and covered buttons. Tuck it in for the office or leave it loose over wide-leg trousers.', '["Satin-finish polyester","Covered button placket","Relaxed fit","Hand wash"]', '["bestseller"]', 4.8, 203, true, '2026-09-16T20:24:26.485Z'),
